  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The rollback theme connects Dawit’s library outage, migration work, runbook ownership, and ferry contribution."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The diagrams explain migration stages, dual writes, and the limits of rollback rather than merely decorating the text."
    },
    "depth": {
      "result": "pass",
      "reason": "The migration progresses from preparation through coexistence and cutover to decommissioning, when the return route disappears."
    },
    "clipart": {
      "result": "fail",
      "reason": "No single central 3D object persists throughout the scroll; the system yields to graphics, typography, and sections explicitly without 3D."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan preserves measurement scope, incidents, team credit, maintenance attribution, and publication limits."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies identity, migration positioning, and contact navigation, with quantified evidence immediately following."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The headline communicates change and reversibility plainly, while the supporting copy establishes credible technical work."
    }
  },
  "copied_example": false,
